    try:
        conn = pymysql.connect(**AIVEN_CONFIG)
    except Exception as e:
        print(f"Connection failed: {e}")
        return 1
    
    processed = []
    try:
        cursor = conn.cursor()
        creator_id = resolve_creator_id(cursor)
        print(f"Using creator_id: {creator_id}")
        
        for i, (title, grade, content, questions) in enumerate(all_courses, 1):
            result = upsert_course(cursor, title, grade, content, questions, creator_id)
            processed.append(result)
            print(f"[{i}/{len(all_courses)}] G{result['grade']:02d} | {result['action'].upper()} | ID {result['id']} | {result['questions']}Q | {title[:40]}...")
        
        conn.commit()
        print(f"\nSuccessfully injected {len(processed)} courses (60 Grade + 65 College)!")
        
    except Exception as e:
        conn.rollback()
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()
        return 1
    finally:
        conn.close()
    return 0

